        c2 = matmul(c, c, p)
        ans = matmul(c2, c, p)

        # C D: a fixed edge entering a zero diagonal loop.
        # D C: a fixed edge leaving a zero diagonal loop.
        for i in range(n):
            if diag_zero[i]:
                for j in range(n):
                    ans[j][i] += c[j][i]
                    ans[i][j] += c[i][j]

        # For a non-loop zero edge i -> j, the only valid placement is
        # (i -> j), (j -> i), (i -> j).
        for i in range(n):
            for j in range(n):
                if i != j and a[i][j] == 0:
                    ans[i][j] += c[j][i]

        for i in range(n):
            for j in range(n):
                ans[i][j] %= p
    else:
        ans = matpow(c, p, p)

        # Add C D + D C.
        for i in range(n):
            if diag_zero[i]:
                for j in range(n):
                    ans[j][i] += c[j][i]
                    ans[i][j] += c[i][j]

